import random
from functools import lru_cache
from book_store import total

PRICES = (0, 800, 1520, 2160, 2560, 3000)

@lru_cache(maxsize=None)
def brute(counts):
    # try EVERY subset of titles (not just the most plentiful) for each group size
    counts = tuple(sorted(counts, reverse=True))
    k = sum(1 for c in counts if c)
    if k == 0:
        return 0
    best = float('inf')
    for g in range(1, k + 1):
        for subset in range(1 << 5):
            if bin(subset).count('1') != g:
                continue
            nxt = tuple(sorted(counts[i] - (1 if subset >> i & 1 else 0) for i in range(5)), reverse=True)
            if any(x < 0 for x in nxt):
                continue
            best = min(best, PRICES[g] + brute(nxt))
    return best

random.seed(42)
for trial in range(3000):
    basket = [random.randint(1, 5) for _ in range(random.randint(0, 14))]
    counts = tuple(sorted((basket.count(t) for t in range(1, 6)), reverse=True))
    if total(basket) != brute(counts):
        print("MISMATCH", basket, total(basket), brute(counts))
        break
else:
    print("3000 random baskets: DP matches full brute force")
